      !UUID.test(descriptor.edition??'')||!SHA.test(descriptor.revision??'')||!UUID.test(descriptor.pricingVersion??'')||
      !UUID.test(descriptor.requestId??'')||!SHA.test(descriptor.requestSha256??''))
