const same = (left, right) => canonical(left) === canonical(right);
const failure = (code, message, status = 422) => Object.assign(new TypeError(message), {code, status});

function requireObject(value, code, message) {
  if (!plain(value)) throw failure(code, message);
  return value;
}

function amount(value, name) {
  if (typeof value !== 'string' || !/^[1-9][0-9]*$/.test(value))
    throw failure('EXACT_ATOMIC_AMOUNT_REQUIRED', `${name} must be a positive integer decimal string.`);
  // The original seller compiler below supplies its authoritative i128 bound.
  if (value.length > 39)
    throw failure('EXACT_ATOMIC_AMOUNT_REQUIRED', `${name} exceeds the original atomic amount range.`);
  return value;
}

/** Locate the original objects; never normalize the source being exported. */
function rawPayments(route) {
  if (own(route, 'offer')) return route.offer.accepts;
  return own(route.definition, 'paymentOptions')
    ? route.definition.paymentOptions : [route.definition.payment];
}

/** The normal service preflight, without opening files or starting a listener. */
function validateSeller(seller) {
  validateSellerServiceConfig(seller);
  const routes = merchantRoutes(seller);
  // Local-only definitions receive the same loopback URL form used at native
  // startup. It is used solely by the original compiler and is never exported.
  const origin = seller.publicOrigin ? new URL(seller.publicOrigin).origin : 'http://127.0.0.1:8423';
  const neverInvoke = () => { throw new Error('Price review does not invoke application code.'); };
  const compiled = compileSellerRoutes(seller.routes.map(route => ({
    id:route.id, maxRequestBytes:route.maxRequestBytes,
    ...(own(route, 'admit') ? {admit:neverInvoke} : {}),
    ...(own(route, 'responseAsset')
      ? {offer:compileAssetRouteOffer(route, origin, compileHttpSellerOffer, !seller.publicOrigin)}
      : own(route, 'offer') ? {offer:route.offer}
        : {definition:{...route.definition, url:origin + route.path}}),
    handler:neverInvoke,
  })), {allowLocalhost:!seller.publicOrigin});
  for (const route of compiled.routes) {
    const source = routes.find(item => item.routeId === route.id);
    if (!source || source.path !== route.path || source.method !== route.method)
      throw failure('SELLER_ROUTE_CHANGED', 'The original seller compiler and saved route identity differ.');
  }
  return routes;
}

/**
 * Produce one complete review from explicit atomic decisions. All untouched
 * source fields and option order remain in the exported seller configuration.
 * File-byte hashes, saved report/version and current-source checks belong to the
 * existing pricing workspace that persists this pure result.
 */
export function createRepricingReview({seller, edits} = {}) {
  requireObject(seller, 'SELLER_REQUIRED', 'Use the original saved seller configuration.');
  const beforeSeller = clone(seller), beforeRoutes = validateSeller(beforeSeller);
  if (!Array.isArray(edits) || !edits.length || edits.length > beforeRoutes.reduce((sum, route) => sum + route.paymentOptions.length, 0))
    throw failure('PRICE_EDITS_REQUIRED', 'Choose one or more original payment options to change.');

  const selected = new Map(), routeIndex = new Map(beforeRoutes.map((route, index) => [route.routeId, index]));
  for (const edit of edits) {
    requireObject(edit, 'INVALID_PRICE_EDIT', 'Each price edit must identify its original route and payment option.');
    if (Object.keys(edit).some(key => !['routeId','paymentIndex','expectedAmount','amount'].includes(key)) ||
        typeof edit.routeId !== 'string' || !routeIndex.has(edit.routeId) ||
        !Number.isSafeInteger(edit.paymentIndex) || edit.paymentIndex < 0)
      throw failure('INVALID_PRICE_EDIT', 'Use a current route ID, zero-based payment option and exact amounts.');
    const route = beforeRoutes[routeIndex.get(edit.routeId)], option = route.paymentOptions[edit.paymentIndex];
    if (!option) throw failure('PAYMENT_OPTION_CHANGED', 'The selected original payment option is unavailable.', 409);
    const expectedAmount = amount(edit.expectedAmount, 'Original amount'), nextAmount = amount(edit.amount, 'New amount');
    if (expectedAmount !== option.atomicAmount)
      throw failure('PAYMENT_AMOUNT_CHANGED', `The saved amount for ${edit.routeId}, option ${edit.paymentIndex + 1}, differs from this edit.`, 409);
    const key = JSON.stringify([edit.routeId, edit.paymentIndex]);
    if (selected.has(key)) throw failure('DUPLICATE_PRICE_EDIT', 'A payment option can appear only once in a price decision.');
    selected.set(key, {routeId:edit.routeId, paymentIndex:edit.paymentIndex, expectedAmount, amount:nextAmount});
  }

  const proposedSeller = clone(beforeSeller), normalizedEdits = [];
  // Walk source order, not request order, for stable review identities.
  for (const route of proposedSeller.routes) {
    for (let paymentIndex = 0; paymentIndex < rawPayments(route).length; paymentIndex++) {
      const edit = selected.get(JSON.stringify([route.id, paymentIndex]));
      if (!edit || edit.amount === edit.expectedAmount) continue;
      rawPayments(route)[paymentIndex].amount = edit.amount;
      normalizedEdits.push(edit);
    }
  }
  if (!normalizedEdits.length) throw failure('PRICE_UNCHANGED', 'Enter at least one amount different from its saved price.');

  const afterRoutes = validateSeller(proposedSeller), changes = [];
  const restored = clone(proposedSeller);
  for (const edit of normalizedEdits) {
    const index = routeIndex.get(edit.routeId), before = beforeRoutes[index].paymentOptions[edit.paymentIndex];
    const after = afterRoutes[index].paymentOptions[edit.paymentIndex];
    const unchangedPayment = {...after, atomicAmount:before.atomicAmount};
    if (!isDeepStrictEqual(before, unchangedPayment))
      throw failure('PAYMENT_IDENTITY_CHANGED', 'Repricing must preserve the complete original payment identity.');
    rawPayments(restored.routes[index])[edit.paymentIndex].amount = edit.expectedAmount;
    const delta = BigInt(edit.amount) - BigInt(edit.expectedAmount);
    changes.push({routeId:edit.routeId, method:beforeRoutes[index].method, path:beforeRoutes[index].path,
      paymentIndex:edit.paymentIndex, before:clone(before), after:clone(after),
      deltaAtomic:delta.toString(), direction:delta > 0n ? 'INCREASE' : 'DECREASE'});
  }
  if (!isDeepStrictEqual(restored, beforeSeller))
    throw failure('SELLER_SOURCE_CHANGED', 'The proposed seller differs outside the selected atomic amounts.');

  return {schema:REPRICING_REVIEW_SCHEMA,
    sellerCanonicalSha256:fingerprint(beforeSeller), proposedSellerCanonicalSha256:fingerprint(proposedSeller),
    edits:normalizedEdits, changes,
    routes:beforeRoutes.map((route, index) => ({routeId:route.routeId, method:route.method, path:route.path,
      before:clone(route.paymentOptions), after:clone(afterRoutes[index].paymentOptions)})),
    changedRoutes:new Set(normalizedEdits.map(edit => edit.routeId)).size,
    changedPaymentOptions:normalizedEdits.length,
    seller:beforeSeller, proposedSeller};
}

/** Rebuild retained decisions through the original compiler before source use. */
export function validateRepricingReview(review) {
  if (!plain(review) || review.schema !== REPRICING_REVIEW_SCHEMA)
    throw failure('REPRICING_REVIEW_REQUIRED', 'Use a retained original repricing review.');
  const rebuilt = createRepricingReview({seller:review.seller, edits:review.edits});
  for (const field of ['sellerCanonicalSha256','proposedSellerCanonicalSha256','edits','changes','routes',
    'changedRoutes','changedPaymentOptions','proposedSeller']) {
    if (!same(review[field], rebuilt[field]))
      throw failure('REPRICING_REVIEW_CHANGED', 'The retained price decision differs from its original seller and selected edits.', 409);
  }
  return rebuilt;
}

function sourceMatches(service, expected, code) {
  if (!isDeepStrictEqual(service, expected))
    throw failure(code, 'The original source inputs do not compile to this exact saved seller configuration. Use its original inputs or export the complete reviewed seller configuration.', 409);
}

/**
 * Prepare unchanged OpenAPI/binding inputs plus repriced original selections.
 * The caller retains exact input bytes and uses the original SF61/SF82 stage
 * commands. No compiled manifest or immutable release is rewritten here.
 */
export function prepareOpenApiRepricing({spec, selections, bindings, review} = {}) {
  const decision = validateRepricingReview(review);
  const originalSpec = clone(spec), originalSelections = clone(selections), originalBindings = clone(bindings);
  const imported = importOpenApi(originalSpec, originalSelections);
  const before = createSellerServiceConfig(imported, originalBindings);
  sourceMatches(before, decision.seller, 'OPENAPI_SOURCE_MISMATCH');
  const proposedSelections = clone(originalSelections), sourceChanges = [];
  const routeIndex = new Map(before.routes.map((route, index) => [route.id, index]));
  for (const edit of decision.edits) {
    const selectionIndex = routeIndex.get(edit.routeId), selection = proposedSelections[selectionIndex];
    if (!selection || selection.accepts?.[edit.paymentIndex]?.amount !== edit.expectedAmount)
      throw failure('OPENAPI_PAYMENT_MISMATCH', 'The original OpenAPI payment selection has changed.', 409);
    selection.accepts[edit.paymentIndex].amount = edit.amount;
    sourceChanges.push({...edit, selectionIndex, method:imported.offers[selectionIndex].method,
      path:imported.offers[selectionIndex].path});
  }
  const proposedImported = importOpenApi(originalSpec, proposedSelections);
  const service = createSellerServiceConfig(proposedImported, originalBindings);
  sourceMatches(service, decision.proposedSeller, 'OPENAPI_REPRICE_MISMATCH');
  return {schema:'stellar-forge.merchant-repricing-openapi.v1',
    source:{kind:'OPENAPI_SELECTIONS', specCanonicalSha256:fingerprint(originalSpec),
      bindingsCanonicalSha256:fingerprint(originalBindings),
      selectionsCanonicalSha256:fingerprint(originalSelections),
      proposedSelectionsCanonicalSha256:fingerprint(proposedSelections)},
    changes:sourceChanges, spec:originalSpec, selections:proposedSelections, bindings:originalBindings,
    imported:proposedImported, service};
}

/**
 * Keep the original API workspace's plan as the editable source. Its original
 * prepareMerchant/savePackage path continues to own auth references, source
 * documents, request contracts, upstreams and release packages.
 */
export function prepareMerchantPlanRepricing({specText, plan, review} = {}) {
  const decision = validateRepricingReview(review), originalPlan = clone(plan);
  const before = prepareMerchant(specText, originalPlan);
  sourceMatches(before.service, decision.seller, 'MERCHANT_PLAN_SOURCE_MISMATCH');
  const proposedPlan = clone(originalPlan), changes = [];
  const routeIndex = new Map(before.service.routes.map((route, index) => [route.id, index]));
  for (const edit of decision.edits) {
    const operationIndex = routeIndex.get(edit.routeId), operation = proposedPlan.operations[operationIndex];
    if (edit.paymentIndex !== 0 || operation?.amountAtomic !== edit.expectedAmount)
      throw failure('MERCHANT_PLAN_PAYMENT_MISMATCH', 'The original merchant plan does not contain this exact selected amount.', 409);
    operation.amountAtomic = edit.amount;
    changes.push({...edit, operationIndex, method:before.imported.offers[operationIndex].method,
      path:before.imported.offers[operationIndex].path});
  }
  const prepared = prepareMerchant(specText, proposedPlan);
  sourceMatches(prepared.service, decision.proposedSeller, 'MERCHANT_PLAN_REPRICE_MISMATCH');
  for (const field of ['facade','bindings','upstreams','transformations']) {
    if (!isDeepStrictEqual(prepared[field], before[field]))
      throw failure('MERCHANT_PLAN_BINDINGS_CHANGED', 'Repricing changed an original API or upstream binding.');
  }
  return {schema:'stellar-forge.merchant-repricing-api-plan.v1',
    source:{kind:'API_MERCHANT_PLAN', originalSourceSha256:createHash('sha256').update(specText).digest('hex'),
      planCanonicalSha256:fingerprint(originalPlan), proposedPlanCanonicalSha256:fingerprint(proposedPlan)},
    changes, plan:proposedPlan, prepared};
}

// MIT. Operator-local HTTP interface for the original merchant pricing workflow.
import { createServer } from 'node:http';
import { readFile } from 'node:fs/promises';
import { randomBytes, timingSafeEqual } from 'node:crypto';
import { pipeline } from 'node:stream/promises';
import { openBundleDownload } from '../economics/archive.mjs';
import { openWorkspace, fault } from './model.mjs';
import { openPlanningWorkspace } from '../planning/workspace.mjs';
import { openTariffWorkspace } from '../tariffs/workspace.mjs';
import { handleTariffRequest } from '../tariffs/server.mjs';

const POLICY = "default-src 'none'; script-src 'self'; style-src 'self'; connect-src 'self'; base-uri 'none'; frame-ancestors 'none'; form-action 'none'";
const REPORT_POLICY = "default-src 'none'; style-src 'unsafe-inline'; base-uri 'none'; frame-ancestors 'none'; form-action 'none'";

export async function startWorkspace({port = 8457, ...options} = {}) {
  if (!Number.isInteger(port) || port < 0 || port > 65535) throw new TypeError('Port must be 0–65535.');
  const model = await openWorkspace(options), token = randomBytes(32).toString('hex');
  const planning = await openPlanningWorkspace({model,directory:options.directory});
  const tariffs = await openTariffWorkspace({model,directory:options.directory});
  const assets = new Map(await Promise.all([
    ['/', 'index.html','text/html; charset=utf-8'],
    ['/economics','../economics/index.html','text/html; charset=utf-8'],
    ['/economics/browser.mjs','../economics/browser.mjs','text/javascript; charset=utf-8'],
    ['/economics/receiving-browser.mjs','../economics/receiving-browser.mjs','text/javascript; charset=utf-8'],
    ['/economics/style.css','../economics/style.css','text/css; charset=utf-8'],
    ['/browser.mjs','browser.mjs','text/javascript; charset=utf-8'],
    ['/style.css','style.css','text/css; charset=utf-8'],
    ['/planning','../planning/index.html','text/html; charset=utf-8'],
    ['/planning/browser.mjs','../planning/browser.mjs','text/javascript; charset=utf-8'],
    ['/planning/style.css','../planning/style.css','text/css; charset=utf-8'],
    ['/tariffs/','../tariffs/public/index.html','text/html; charset=utf-8'],
    ['/tariffs/browser.mjs','../tariffs/public/browser.mjs','text/javascript; charset=utf-8'],
    ['/tariffs/style.css','../tariffs/public/style.css','text/css; charset=utf-8'],
  ].map(async ([path,name,type]) => [path,{type,bytes:await readFile(new URL(name,import.meta.url))}])));
  let hosts = new Set(), origins = new Set();
  const server = createServer((req,res) => {
    function reply(status,type,data,extra = {}) {
      if (res.destroyed) return;
      const bytes = Buffer.isBuffer(data) ? data : Buffer.from(typeof data === 'string' ? data : JSON.stringify(data));
      res.writeHead(status,{'content-type':type,'content-length':String(bytes.length),'cache-control':'no-store',
        'x-content-type-options':'nosniff','referrer-policy':'no-referrer',
        'cross-origin-resource-policy':'same-origin','content-security-policy':POLICY,...extra});
      res.end(req.method === 'HEAD' ? undefined : bytes);
    }
    const json = (status,value) => reply(status,'application/json; charset=utf-8',value);
    function authorize() {
      const supplied = Buffer.from(String(req.headers['x-sf97-workspace'] ?? ''));
      const expected = Buffer.from(token);
      if (supplied.length !== expected.length || !timingSafeEqual(supplied,expected))
        throw fault('WORKSPACE_SESSION_REQUIRED','Reload this workspace before saving.',403);
    }
    async function body(maximum = 2 * 1024 * 1024) {
      if (req.headers['content-type']?.split(';')[0].trim().toLowerCase() !== 'application/json')
        throw fault('JSON_REQUIRED','Use application/json.',415);
      authorize();
      let size = 0; const chunks = [];
      for await (const chunk of req) {
        size += chunk.length;
        if (size > maximum) throw fault('REQUEST_TOO_LARGE','Input exceeds the documented workspace size limit.',413);
        chunks.push(chunk);
      }
      try {
        const value = JSON.parse(Buffer.concat(chunks).toString('utf8'));
        if (!value || typeof value !== 'object' || Array.isArray(value)) throw new Error();
        return value;
      } catch { throw fault('INVALID_JSON','Use a JSON object for commercial inputs.'); }
    }
    (async () => {
      if (!hosts.has(req.headers.host) || (req.headers.origin && !origins.has(req.headers.origin)) ||
          ['cross-site','same-site'].includes(req.headers['sec-fetch-site']))
        throw fault('OPERATOR_ORIGIN_REQUIRED','Open the local operator workspace directly.',403);
      const url = new URL(req.url,`http://${req.headers.host}`);
      if (url.hash || (url.search && !['/api/tariffs/source','/api/tariffs/repricing/source'].includes(url.pathname)))
        throw fault('INVALID_URL','Use the workspace URL without query parameters.',400);
      if ((url.pathname === '/api/tariffs' || url.pathname.startsWith('/api/tariffs/')) &&
          await handleTariffRequest({req,res,url,workspace:tariffs,prefix:'/api/tariffs',authorize,json,reply,body})) return;
      if (req.method === 'GET' || req.method === 'HEAD') {
        if (url.pathname === '/tariffs') return reply(308,'text/plain; charset=utf-8','Open the tariff workspace.',{location:'/tariffs/'});
        const asset = assets.get(url.pathname);
        if (asset) return reply(200,asset.type,asset.bytes);
        if (url.pathname === '/api/economics/state') return json(200,{...await model.economics.state(),token});
        const costFile = /^\/cost-files\/(source|export|edition|received)\/([a-f0-9-]{36})(?:\/(.+))?$/.exec(url.pathname);
        if (costFile) {
          if (costFile[1] === 'source' && !costFile[3]) {
            const value=await model.economics.sourceDownload(costFile[2]);
            return reply(200,'application/octet-stream',value.bytes,{'content-disposition':'attachment; filename="'+value.source.metadata.name.replace(/[^a-zA-Z0-9_.-]/g,'_')+'"'});
          }
          if (costFile[1] === 'edition' && costFile[3]) {
            const name=decodeURIComponent(costFile[3]),bytes=await model.economics.download(costFile[2],name);
            return reply(200,name.endsWith('.csv')?'text/csv; charset=utf-8':'application/json; charset=utf-8',bytes,
              {'content-disposition':'attachment; filename="'+name.replace(/[^a-zA-Z0-9_.-]/g,'_')+'"'});
          }
          if (costFile[1] === 'received' && costFile[3]) {
            const file=await model.economics.receiving.download(costFile[2],decodeURIComponent(costFile[3]));
            return reply(200,'application/octet-stream',file.bytes,
              {'content-disposition':'attachment; filename="'+file.name.replace(/[^a-zA-Z0-9_.-]/g,'_')+'"','x-content-sha256':file.sha256});
          }
          if (['export','received'].includes(costFile[1]) && !costFile[3]) {
            const file=await (costFile[1]==='received'?model.economics.receiving.archiveFile(costFile[2]):model.economics.exportFile(costFile[2])),
              opened=await openBundleDownload(file);
            try{
              res.writeHead(200,{'content-type':'application/x-tar','content-length':String(file.bytes),
                'content-disposition':'attachment; filename="'+file.filename+'"','cache-control':'no-store',
                'x-content-type-options':'nosniff','referrer-policy':'no-referrer','cross-origin-resource-policy':'same-origin',
                'content-security-policy':POLICY});
              if(req.method==='HEAD')res.end();else await pipeline(opened.stream(),res);
            }finally{await opened.close();}
            return;
          }
          throw fault('NOT_FOUND','Cost file not found.',404);
        }
        if (url.pathname === '/api/state') return json(200,{...await model.state(),token});
        if (url.pathname === '/api/planning/state') return json(200,await planning.list());
        const match = /^\/(files|repricing-files|planning-files)\/([a-f0-9-]{36})\/(.+)$/.exec(url.pathname);
        if (match) {
          const name = decodeURIComponent(match[3]);
          const bytes = await (match[1] === 'planning-files' ? planning.download(match[2],name)
            : match[1] === 'repricing-files' ? model.downloadRepricing(match[2],name)
            : model.download(match[2],name)), last = name.split('/').at(-1);
          const html = name.endsWith('.html');
          const type = html ? 'text/html; charset=utf-8' : name.endsWith('.json')
            ? 'application/json; charset=utf-8' : name.endsWith('.csv') ? 'text/csv; charset=utf-8' : 'application/octet-stream';
          return reply(200,type,bytes,{'content-security-policy':REPORT_POLICY,
            ...(html ? {} : {'content-disposition':`attachment; filename="${last.replace(/[^a-zA-Z0-9_.-]/g,'_')}"`})});
        }
        throw fault('NOT_FOUND','Workspace page not found.',404);
      }
      if (req.method !== 'POST') return reply(405,'text/plain','Use GET or POST.',{allow:'GET, HEAD, POST'});
      const receivedUpload = /^\/api\/economics\/received-uploads\/([a-f0-9-]{36})$/.exec(url.pathname);
      if(receivedUpload){
        authorize();
        if(req.headers['content-type']?.split(';')[0].trim().toLowerCase()!=='application/octet-stream')
          throw fault('BUNDLE_BODY_REQUIRED','Send the complete original archive bytes.',415);
        const header=req.headers['x-sf97-received'];let metadata;
        if(typeof header!=='string'||header.length>12000)throw fault('BUNDLE_METADATA_REQUIRED','Name the original received package.');
        try{metadata=JSON.parse(decodeURIComponent(header));}catch{throw fault('BUNDLE_METADATA_INVALID','The received package metadata is invalid.');}
        return json(200,await model.economics.receiving.receive({...metadata,requestId:receivedUpload[1],body:req}));
      }
      const upload = /^\/api\/economics\/uploads\/([a-f0-9-]{36})$/.exec(url.pathname);
      if (upload) {
        authorize();let metadata;
        const header=req.headers['x-sf97-source'];
        if(typeof header!=='string'||header.length>12000)throw fault('SOURCE_METADATA_REQUIRED','Provide the original source metadata header.');
        try{metadata=JSON.parse(decodeURIComponent(header));}catch{throw fault('SOURCE_METADATA_INVALID','Source metadata header is invalid.');}
        return json(200,await model.economics.upload({requestId:upload[1],metadata,body:req}));
      }
      const input = await body(url.pathname.startsWith('/api/economics/') ? 32*1024*1024 : 2*1024*1024);
      const costActions = {
        '/api/economics/list':()=>model.economics.list(input),
        '/api/economics/pricing':()=>model.economics.pricing(input.version),
        '/api/economics/source-inspect':()=>model.economics.inspectSource(input.sourceId,input),
        '/api/economics/map-charges':()=>model.economics.mapCharges(input),
        '/api/economics/capture':()=>model.economics.capture(input),
        '/api/economics/weights':()=>model.economics.weights(input),
        '/api/economics/preview':()=>model.economics.preview(input),
        '/api/economics/save':()=>model.economics.save(input),
        '/api/economics/edition':()=>model.economics.edition(input.edition),
        '/api/economics/compare':()=>model.economics.compare(input),
        '/api/economics/proposal':()=>model.economics.proposal(input),
        '/api/economics/apply-pricing':()=>model.economics.applyPricing(input),
        '/api/economics/export':()=>model.economics.bundle(input),
        '/api/economics/received':()=>model.economics.receiving.inspect(input.packageId),
        '/api/economics/received-request':()=>model.economics.receiving.request(input.packageId),
        '/api/economics/received-review':()=>model.economics.receiving.reviewDraft(input),
        '/api/economics/received-import':()=>model.economics.receiving.importDraft(input),
        '/api/economics/received-drafts':()=>model.economics.receiving.draftSummaries(input.packageId),
        '/api/economics/received-draft':()=>model.economics.receiving.reopenDraft(input.packageId,input.requestId),
      };
      if(Object.hasOwn(costActions,url.pathname))return json(200,await costActions[url.pathname]());
      if (url.pathname === '/api/planning/source') return json(200,await planning.source(input.version));
      if (url.pathname === '/api/planning/preview') return json(200,await planning.preview(input));
      if (url.pathname === '/api/planning/save') return json(200,await planning.save(input));
      if (url.pathname === '/api/planning/load') return json(200,await planning.load(input.planId));
      if (url.pathname === '/api/planning/apply') return json(200,await planning.selection(input));
      if (url.pathname === '/api/source') return json(200,{...await model.state(input.selection),token});
      if (url.pathname === '/api/preview') return json(200,await model.preview(input));
      if (url.pathname === '/api/save') return json(200,await model.save(input));
      if (url.pathname === '/api/load-version') return json(200,await model.loadVersion(input.version));
      if (url.pathname === '/api/compare') return json(200,await model.compare(input));
      if (url.pathname === '/api/repricing/source') return json(200,await model.repricingSource(input.version));
      if (url.pathname === '/api/repricing/preview') return json(200,await model.previewRepricing(input));
      if (url.pathname === '/api/repricing/save') return json(200,await model.saveRepricing(input));
      if (url.pathname === '/api/repricing/stage') return json(200,await model.stageRepricing(input));
      throw fault('NOT_FOUND','Workspace operation not found.',404);
    })().catch(error => json(error.status ?? (error instanceof TypeError || error instanceof RangeError ? 422 : 500),
      {code:error.code ?? 'WORKSPACE_OPERATION_FAILED',
        message:error.status || error instanceof TypeError || error instanceof RangeError ? error.message : 'Workspace operation failed. Check the configured private source and state directory.'}));
  });
  server.requestTimeout = 30*60*1000; server.headersTimeout = 10000; server.keepAliveTimeout = 2000;
  await new Promise((done,fail) => {
    const onError = error => { server.removeListener('listening',onListen); fail(error); };
    const onListen = () => { server.removeListener('error',onError); done(); };
    server.once('error',onError); server.once('listening',onListen); server.listen(port,'127.0.0.1');
  });
  const assigned = server.address().port;
  hosts = new Set([`127.0.0.1:${assigned}`,`localhost:${assigned}`]);
  origins = new Set([...hosts].map(host => `http://${host}`));
  let closing;
  return {url:`http://127.0.0.1:${assigned}`,planningUrl:`http://127.0.0.1:${assigned}/planning`,
    tariffsUrl:`http://127.0.0.1:${assigned}/tariffs/`,server,model,planning,tariffs,
    close() { return closing ??= new Promise((done,fail) => {
      server.close(error => error ? fail(error) : done()); server.closeIdleConnections?.();
    }); }};
}

